<?php
$page_title='โปรโมชันสินค้า MALL';require_once __DIR__.'/../includes/auth_check.php';requireAdmin();require_once __DIR__.'/../config/database.php';$db=(new Database())->getConnection();$message=$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);try{$action=$_POST['action']??'';
 if($action==='sale'){$id=(int)($_POST['product_id']??0);$price=(float)($_POST['sale_price']??0);$compare=(float)($_POST['compare_at_price']??0);$start=$_POST['starts_at']??'';$end=$_POST['ends_at']??'';if($price<=0||$compare<=$price||strtotime($end)<=strtotime($start))throw new RuntimeException('ราคาลดต้องต่ำกว่าราคาเดิม และวันสิ้นสุดต้องอยู่หลังวันเริ่ม');$q=$db->prepare('UPDATE products SET compare_at_price=?,sale_price=?,sale_starts_at=?,sale_ends_at=?,sale_stock=?,video_url=?,fulfillment_type=? WHERE id=? AND seller_id IS NULL');$q->execute([$compare,$price,$start,$end,max(1,(int)$_POST['sale_stock']),trim((string)$_POST['video_url']),'platform',$id]);if(!$q->rowCount())throw new RuntimeException('ไม่พบสินค้า MALL ที่เลือก');auditLog($db,'admin.mall.flash_sale','product',$id,null,['sale_price'=>$price,'starts_at'=>$start,'ends_at'=>$end]);$message='บันทึก Flash Sale ของ MALL แล้ว';
 }elseif($action==='coupon'){$code=strtoupper(trim((string)$_POST['code']));$type=$_POST['discount_type']??'';if(!preg_match('/^[A-Z0-9_-]{4,40}$/',$code)||!in_array($type,['percent','fixed','free_shipping'],true))throw new RuntimeException('รหัสคูปองหรือรูปแบบส่วนลดไม่ถูกต้อง');$q=$db->prepare('INSERT INTO coupons(seller_id,mall_only,code,title,description,discount_type,discount_value,max_discount,min_order_amount,usage_limit,per_user_limit,starts_at,ends_at) VALUES(NULL,1,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$code,trim((string)$_POST['title']),'คูปองสินค้า MALL',$type,(float)$_POST['discount_value'],(float)$_POST['max_discount']?:null,(float)$_POST['min_order_amount'],(int)$_POST['usage_limit']?:null,max(1,(int)$_POST['per_user_limit']),$_POST['starts_at'],$_POST['ends_at']]);auditLog($db,'admin.mall.coupon.create','coupon',(int)$db->lastInsertId(),null,['code'=>$code]);$message='สร้างคูปอง MALL แล้ว';
 }elseif($action==='bundle'){$ids=array_values(array_unique(array_map('intval',$_POST['products']??[])));if(count($ids)<2)throw new RuntimeException('เลือกสินค้า MALL อย่างน้อย 2 รายการ');$db->beginTransaction();$q=$db->prepare('INSERT INTO product_bundles(seller_id,title,discount_percent,minimum_items,starts_at,ends_at) VALUES(NULL,?,?,?,?,?)');$q->execute([trim((string)$_POST['title']),(float)$_POST['discount_percent'],count($ids),$_POST['starts_at'],$_POST['ends_at']]);$bundle=(int)$db->lastInsertId();$check=$db->prepare('SELECT id FROM products WHERE id=? AND seller_id IS NULL');$add=$db->prepare('INSERT INTO product_bundle_items(bundle_id,product_id) VALUES(?,?)');foreach($ids as $id){$check->execute([$id]);if(!$check->fetchColumn())throw new RuntimeException('พบสินค้าที่ไม่ใช่สินค้า MALL');$add->execute([$bundle,$id]);}$db->commit();auditLog($db,'admin.mall.bundle.create','bundle',$bundle,null,['products'=>$ids]);$message='สร้าง Bundle ของ MALL แล้ว';
 }}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$products=$db->query("SELECT * FROM products WHERE seller_id IS NULL AND approval_status='approved' ORDER BY name")->fetchAll();$start=date('Y-m-d\TH:i');$end=date('Y-m-d\TH:i',strtotime('+7 days'));require_once __DIR__.'/../includes/admin_header.php';?>
